CREATE OR REPLACE FUNCTION public.can_read_factory(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND _uid=auth.uid() AND EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=_uid AND is_active) AND (public.can_write_factory(_uid) OR public.can_view_running_bill(_uid)) $$;
ALTER TABLE public.factory_report_quantities ADD CONSTRAINT factory_quantities_finite CHECK(today_qty<'Infinity'::numeric);
ALTER TABLE public.factory_report_expenses ADD CONSTRAINT factory_expenses_finite CHECK(amount_inr<'Infinity'::numeric);
CREATE FUNCTION public._factory_validate_subcontracts(p_report_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q record; s public.subcontract_rates; used numeric; BEGIN IF NOT public.can_write_factory(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; FOR q IN SELECT DISTINCT x.contractor_id,x.boq_item_id,m.project_id FROM public.factory_report_quantities x JOIN public.modules m ON m.id=x.module_id WHERE x.report_id=p_report_id AND NOT x.is_archived AND x.contractor_id IS NOT NULL AND x.today_qty>0 LOOP SELECT * INTO s FROM public.subcontract_rates WHERE project_id=q.project_id AND contractor_id=q.contractor_id AND boq_item_id=q.boq_item_id AND is_active; IF s.id IS NULL THEN RAISE EXCEPTION 'No rate for this contractor on this item. Ask Planning to add it in Setup.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('subcontract-rate:'||s.id::text,0)); IF s.rate_type='lump_sum' THEN SELECT coalesce(sum(x.today_qty),0) INTO used FROM public.factory_report_quantities x JOIN public.factory_daily_reports r ON r.id=x.report_id WHERE x.boq_item_id=q.boq_item_id AND x.contractor_id=q.contractor_id AND NOT x.is_archived AND NOT r.is_archived AND (r.status='submitted' OR r.id=p_report_id); IF used>s.package_qty THEN RAISE EXCEPTION 'This takes the lump-sum package past its total'; END IF; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public._factory_validate_subcontracts(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public._factory_validate_subcontracts(uuid) TO service_role;
DO $patch$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.save_factory_report_draft(date,jsonb)'::regprocedure); IF position('IF r.status=''submitted'' THEN PERFORM public.submit_factory_report' IN d)=0 THEN RAISE EXCEPTION 'Draft validation anchor missing'; END IF; d:=replace(d,'IF r.status=''submitted'' THEN PERFORM public.submit_factory_report','PERFORM public._factory_validate_subcontracts(r.id); IF r.status=''submitted'' THEN PERFORM public.submit_factory_report'); EXECUTE d;
d:=pg_get_functiondef('public.save_site_report_draft(uuid,date,jsonb)'::regprocedure); d:=replace(d,'IF EXISTS(SELECT 1 FROM public.project_boq_items WHERE id=v_bid AND work_location=''factory'')','IF v_q>0 AND EXISTS(SELECT 1 FROM public.project_boq_items WHERE id=v_bid AND work_location=''factory'')'); EXECUTE d; END $patch$;